ts_interface_examples:
// TypeScript example (simplified)
interface ToolSpec<TArgs, TResult> { name: string; argSchema?: string; handler: (args: TArgs) => Promise<TResult>; }
interface StreamEvent { event: 'delta'|'final'|'tool_call'|'tool_result'|'validation_warning'|'error'; token?: string; payload: string; }
// Client init
const client = new RedwoodClient({ tools: [ { name: 'lookup_user', argSchema: 'https://schemas.redwood.company/lookup_user.json', handler: async (args) => backend.lookup(args.id) } ] });
// Streaming call with per-event callback
await client.stream({ model: 'rw-3b', schema: 'https://schemas.redwood.company/chat_response.json' }, (evt: StreamEvent) => { if (evt.event === 'delta') applyDelta(evt.payload); if (evt.event === 'tool_call') runLocalTool(JSON.parse(evt.payload)); });

go_interface_examples:
// Go example (simplified)
type ToolSpec struct { Name string; ArgSchema string; Handler func(map[string]any) (map[string]any, error) }
type StreamEvent struct { Event string; Token string; Payload string }
// registration
tools := []ToolSpec{{Name: "calc", ArgSchema: "https://schemas/.../calc.json", Handler: CalcHandler}}
client := NewRedwoodClient(Config{Tools: tools})
// streaming loop
for evt := range client.Stream(StreamRequest{Model: "rw-3b"}) { switch evt.Event { case "delta": applyDelta(evt.Payload) case "tool_call": go handleToolCall(evt.Payload) } }
